const raw = $input.first().json;
const records = Array.isArray(raw) ? raw : [raw];

if (records.length === 0 || !records[0].sync_session_id) {
  return [];
}

const record = records[0];
return [{
  json: {
    telemetry_id: record.id,
    sync_session_id: record.sync_session_id,
    farm_id: record.farm_id,
    owner_id: record.owner_id,
    production_type: record.production_type,
    record_count: record.record_count ?? null,
    synced_at: record.synced_at ?? new Date().toISOString()
  }
}];

const rawInput = $input.all();
const records = rawInput.length === 1 && Array.isArray(rawInput[0].json)
  ? rawInput[0].json
  : rawInput.map(item => item.json);
const session = $('Extract Sync Session').first().json;
const model = $env.DEEPSEEK_MODEL || 'deepseek-chat';

if (records.length === 0) {
  throw new Error('No health records found for sync_session_id: ' + session.sync_session_id);
}

const recordsBlock = records.map((r, i) =>
  (i + 1) + '. Record ID: ' + r.id + ' | Animal: ' + (r.animal_id || 'N/A') + ' | Symptoms: ' + r.symptoms_description
).join(' || ');

const systemPrompt = 'You are FincApp\'s veterinary AI analyst for Colombian and Latin American livestock. Analyze batches of health records and return structured JSON in English only. Respond ONLY with a valid JSON object.';

const userPrompt = 'Batch of ' + records.length + ' records from a ' + session.production_type + ' farm. Farm: ' + session.farm_id + '. Records: ' + recordsBlock + '. Return JSON object with results array. Each element: record_id, severity (low/medium/high/critical), summary, contagion_risk (bool), immediate_action_required (bool).';

return [{
  json: {
    sync_session_id: session.sync_session_id,
    farm_id: session.farm_id,
    owner_id: session.owner_id,
    production_type: session.production_type,
    record_count: records.length,
    llm_model: model,
    prompt_system: systemPrompt,
    prompt_user: userPrompt
  }
}];

const response = $input.first().json;
const upstream = $('Build Batch LLM Prompt').first().json;

if (!response.choices || response.choices.length === 0) {
  throw new Error('LLM returned no choices — check DEEPSEEK_API_KEY env var');
}

let parsed;
try {
  parsed = JSON.parse(response.choices[0].message.content);
} catch (e) {
  throw new Error('LLM response is not valid JSON: ' + response.choices[0].message.content);
}

const results = Array.isArray(parsed) ? parsed : (parsed.results ?? []);
if (results.length === 0) {
  throw new Error('LLM returned empty results array');
}

const validSeverities = ['low', 'medium', 'high', 'critical'];
for (const item of results) {
  if (!item.record_id || !item.severity) throw new Error('LLM result missing record_id or severity');
  if (!validSeverities.includes(item.severity)) throw new Error('Invalid severity: ' + item.severity);
}

return [{
  json: {
    sync_session_id: upstream.sync_session_id,
    farm_id: upstream.farm_id,
    owner_id: upstream.owner_id,
    production_type: upstream.production_type,
    record_count: upstream.record_count,
    results,
    llm_model: response.model,
    tokens_used: response.usage?.total_tokens ?? null,
    evaluated_at: new Date().toISOString()
  }
}];
